import{_ as e,o as a,c as s,aj as i}from"./framework.js";const k=JSON.parse('{"title":"Style（站点样式） | TemplateEngine / Css | Documentation","description":"Style 是 Kooboo 站点中独立保存的 CSS 文件，注册后通过 URL 访问（例如 /assets/site.css）。用于全站主题、组件库补丁、不适合写在每个 Page 里的样式。","frontmatter":{"title":"Style（站点样式） | TemplateEngine / Css | Documentation","description":"Style 是 Kooboo 站点中独立保存的 CSS 文件，注册后通过 URL 访问（例如 /assets/site.css）。用于全站主题、组件库补丁、不适合写在每个 Page 里的样式。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/templateEngine/css/index.html"}]]},"headers":[],"relativePath":"zh/templateEngine/css/index.md","filePath":"templateEngine/css/index.md","lastUpdated":1780023555000}'),o={name:"zh/templateEngine/css/index.md"};function d(l,t,n,h,r,c){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="style-站点样式" tabindex="-1">Style（站点样式） <a class="header-anchor" href="#style-站点样式" aria-label="Permalink to &quot;Style（站点样式）&quot;">​</a></h1><blockquote><p>带路由的 <code>.css</code> 资源：全局主题、补丁与 Layout <code>&lt;head&gt;</code> 引用</p></blockquote><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p><strong>Style</strong> 是 Kooboo 站点中独立保存的 CSS 文件，注册后通过 <strong>URL</strong> 访问（例如 <code>/assets/site.css</code>）。用于全站主题、组件库补丁、不适合写在每个 Page 里的样式。</p><p>由 <strong><code>k.site.styles</code></strong> 管理，见 <a href="/kb-docs/zh/api/site/css.html">k.site.styles</a>。</p><h2 id="在模板中引用" tabindex="-1">在模板中引用 <a class="header-anchor" href="#在模板中引用" aria-label="Permalink to &quot;在模板中引用&quot;">​</a></h2><p>在 Layout（推荐）或 Page 的 <code>&lt;head&gt;</code>：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/assets/site.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><code>href</code> 为 Style 资源的访问路径。服务端可用 <code>k.site.styles.getUrl(id)</code> 获取相对 URL。</p><h2 id="与-tailwind、内联样式" tabindex="-1">与 Tailwind、内联样式 <a class="header-anchor" href="#与-tailwind、内联样式" aria-label="Permalink to &quot;与 Tailwind、内联样式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>Tailwind CDN</td><td>常在 Layout 引入 <code>https://www.kooboo.com/tailwindcss.js</code>，utility class 直接写在 HTML</td></tr><tr><td>Style 资源</td><td>复杂动画、全局变量、第三方组件库补丁（如 Element Plus + Tailwind 权重修正）</td></tr><tr><td>Page/View 内 <code>&lt;style&gt;</code></td><td>仅影响单页或单区块时使用</td></tr></tbody></table><p>多数布局类样式优先 Tailwind；重复少、需集中维护的规则放进 Style 资源。</p><h2 id="与-script-的对称关系" tabindex="-1">与 Script 的对称关系 <a class="header-anchor" href="#与-script-的对称关系" aria-label="Permalink to &quot;与 Script 的对称关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Style</th><th>Script</th></tr></thead><tbody><tr><td>标签</td><td><code>&lt;link rel=&quot;stylesheet&quot;&gt;</code></td><td><code>&lt;script src=&quot;...&quot;&gt;</code></td></tr><tr><td>典型位置</td><td>Layout <code>&lt;head&gt;</code></td><td>Layout <code>&lt;head&gt;</code> 或 Page 底部</td></tr><tr><td>API</td><td><code>k.site.styles</code></td><td><code>k.site.scripts</code></td></tr></tbody></table><p>二者均支持路由 URL 与版本日志；Layout / View <strong>没有</strong> 独立 URL。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../layout/">Layout</a></li><li><a href="./../js/">Script</a></li><li><a href="/kb-docs/zh/api/site/css.html">k.site.styles</a></li></ul>',17)])])}const u=e(o,[["render",d]]);export{k as __pageData,u as default};
